file.content:
if force_sync_pending:
    logger.updateConfig({"force_sync_pending": True, "paused": paused})
else:
    logger.deleteConfig("force_sync_pending")
    logger.deleteConfig("paused")
if sync_job_id:
    logger.updateConfig({"sync_job_id": sync_job_id})
else:
    logger.deleteConfig("sync_job_id")
tracer.set_tag("crawl_id", crawl_id)
resource = function_to_resource_map[integration_type][function_name](integration)

crawl_frequency = resolve_crawl_frequency(
    connection_row, org_row, resource, function_name
)
due = True
if not sync_job_id:
    due = crawl_due(row_to_check, crawl_frequency)
if force or force_sync_pending:
    pass
elif not due and row_to_check.get("last_crawl_end"):
    logger.info(
        f"Crawl task {function_name} for connection {connection_id} is not due"
    )
    if not DRY_RUN:
        return

# start_time_str will be None if it's first crawl and it's never been started before.
# if it has been started before, first_crawl will be True but start_time_str will have a value.
# it might have latest_data too.
if first_crawl and not start_time_str:  # always False for sync jobs
    first_crawl_lookback_days = get_first_crawl_lookback_days(
        org_row, integration_type
    )
    if (
        org_id in INTEGRATION_SPECIFIC_LOOKBACK_DAYS_ORGS
        and integration_name in INTEGRATION_SPECIFIC_LOOKBACK_DAYS_ORGS[org_id]
        and function_name
        in INTEGRATION_SPECIFIC_LOOKBACK_DAYS_ORGS[org_id][integration_name]
    ):
        first_crawl_lookback_days = INTEGRATION_SPECIFIC_LOOKBACK_DAYS_ORGS[org_id][
            integration_name
        ][function_name]
    start_time_str = dt_to_str(
        str_to_dt(created_at) - timedelta(days=first_crawl_lookback_days)
    )
    logger.updateConfig({"start_time": f"{start_time_str} (first crawl)"})
if not start_time_str:  # always present for sync jobs
    start_time_str = created_at
if not end_time_str:  # always present for sync jobs
    end_time_str = dt_to_str(now())
    logger.updateConfig({"end_time": f"{end_time_str} (none)"})
start_time_dt = str_to_dt(start_time_str) - timedelta(
    minutes=integration.crawl_start_overlap_minutes
)
end_time_dt = str_to_dt(end_time_str)
logger.info(f"Starting crawl from {start_time_str} to {end_time_str}")

table_name = resource.table_name()

page = 1
if not DRY_RUN:
    current_time = dt_to_str(now())
    should_force_replace_submit = False if page_token else True
    # fully replace submit, not update ONLY if no page token
    # if there is a page token, we want to keep track of the tasks that were started since that data will not be crawled/submitted again
    # case we need to handle: the first submit task finishes before the last submit task is started
    # if one len > 50, get intersection of the two
    # make a SEPARATE api call that removes these from both lists

    if sync_job_id:
        update_sync_job(
            sync_job_id,
            {
                "last_crawl_start": current_time,
                "submit": {
                    "tasks_started": {""},
                    "tasks_finished": {""},
                    "mark_complete": False,
                },
            },
            force_replace_submit=should_force_replace_submit,
        )
    else:
        update_items = {
            "last_crawl_start": current_time,
            "submit": {"tasks_started": {""}, "tasks_finished": {""}},
            # dynamo doesn't support empty sets
            "stale": stale,
            "paused": paused,
            "org_id": org_id,
            "integration_type": integration_type,
        }
        update_crawl_items(
            connection_id,
            function_name,
            update_items,
            force_replace_submit=should_force_replace_submit,
        )

worker_hostname = self.request.hostname
stop_event = heartbeat_thread = None
if not no_heartbeat:
    stop_event = threading.Event()
    heartbeat_thread = threading.Thread(
        target=send_heartbeat,
        args=(
            worker_hostname,
            stop_event,
            connection_id,
            function_name,
            dict(logger.config),
            sync_job_id,
        ),
    )
    heartbeat_thread.daemon = True
    # start heartbeat right before we start crawling logic
    heartbeat_thread.start()

if protected:
    ecs_task_protection_request(True, connection_row, function_name)

# start resource tracking for this specific task
# tracemalloc.start()
# snapshot_start = tracemalloc.take_snapshot()
# cpu_time_start = time.process_time()

max_pages = int(os.environ.get("MAX_PAGES", 0))

# emit completion webhook for enqueued or retried force-sync
# internal local runs (yarn crawl-hard -f, at a tty) stay silent
notify_force_sync = (force or force_sync_pending) and not (
    sys.stdin and sys.stdin.isatty()
)

next_token = page_token or "default"
current_start_dt = str_to_dt(start_time_str)
first_loop = True
total_rows_submitted = 0
linked_resource_key = resource.linked_resource_key
linked_ids_seen: set = set()
with integration.crawl_scope(resource):
    while next_token:
        next_token_to_check = deepcopy(next_token)
        logger.info(f"Getting page {page} of data")
        try:
            rsp, child_resource_rsp, page_submit_task_ids = get_and_submit(
                resource,
                start_time_dt,
                end_time_dt,
                first_crawl,
                first_loop,
                next_token,
                local_submit,
                sync_job_id=sync_job_id,
                notify_force_sync=notify_force_sync,
            )
            # first crawls already pull every parent via its own backfill, so the
            # linked-refresh fan-out here would be redundant and hammer the vendor
            if linked_resource_key and not first_crawl:
                for row in rsp["data"]:
                    fk = row.get(linked_resource_key)
                    if fk:
                        linked_ids_seen.add(str(fk))
            first_loop = False
        except Exception as e:
            if not SKIP_FILE_CLEANUP:
                integration.cleanup_staged_files()
            if isinstance(e, PokedexException):
                logger.updateConfig({"status_code": e.status_code})
            else:
                logger.deleteConfig("status_code")
            if not DRY_RUN:
                current_time = dt_to_str(now())
                # transient first-crawl failures (retriable soon, or a source dependency
                # not ready) skip last_crawl_end so the scheduler retries next tick, not next cadence.
                retriable_soon = (
                    isinstance(e, RetryException)
                    and e.retry_after_seconds <= HEARTBEAT_TIMEOUT
                )
                dependency_not_ready = isinstance(
                    e, DependencyFirstCrawlIncompleteException
                )
                skip_last_crawl_end = (
                    first_crawl
                    and crawl_frequency > HEARTBEAT_TIMEOUT
                    and (retriable_soon or dependency_not_ready)
                )
                if sync_job_id:
                    update_sync_job(
                        sync_job_id,
                        {"last_crawl_end": current_time},
                    )
                elif not skip_last_crawl_end:
                    update_items = {"last_crawl_end": current_time}
                    update_crawl_items(connection_id, function_name, update_items)
            if stop_event and heartbeat_thread:  # not no_heartbeat
                # Signal the heartbeat thread to stop
                stop_event.set()
                # Wait for the heartbeat thread to finish
                heartbeat_thread.join()
            if protected:
                # disable task protection
                ecs_task_protection_request(False, connection_row, function_name)
            # ensure tracemalloc is stopped on error
            if tracemalloc.is_tracing():
                tracemalloc.stop()
            raise e
        logger.deleteConfig("status_code")
        if rsp["next_token"] == next_token_to_check:
            raise PokedexException(
                f"Next token did not change: {next_token_to_check}",
                500,
                origin="trackstar",
            )
        data, next_token = rsp["data"], rsp["next_token"]
        next_start = rsp.get("next_start")
        if next_start:
            if next_start == current_start_dt:
                raise PokedexException(
                    f"next_start did not change: {dt_to_str(next_start)}",
                    500,
                    origin="trackstar",
                )
            if not current_start_dt < next_start <= end_time_dt:
                raise PokedexException(
                    f"next_start {dt_to_str(next_start)} is not inside the remaining "
                    f"crawl range ({dt_to_str(current_start_dt)} to {end_time_str})",
                    500,
                    origin="trackstar",
                )
            if next_start == end_time_dt:
                next_start = None
        if not DRY_RUN:
            if sync_job_id:
                update_items = {
                    "submit": {"tasks_started": page_submit_task_ids},
                }
                if resource.store_page_token():
                    update_items["latest_page_token"] = next_token
                    update_items["last_page_token_update"] = dt_to_str(now())
                if next_start:
                    # the job picks back up from its latest_data, so record where
                    # this window got to before the crawl moves past it
                    update_items["submit"]["set_latest_data"] = dt_to_str(
                        next_start
                    )
                if not next_token and not next_start:
                    update_items["submit"]["mark_complete"] = True
                update_sync_job(sync_job_id, update_items)
            else:
                update_items: dict[str, object] = {
                    "submit": {"tasks_started": page_submit_task_ids},
                }
                # deferred page token only used for royal mail to store state and exit gracefully
                deferred_page_token = rsp.get("deferred_page_token")
                if next_start:
                    update_items["submit"]["set_latest_data"] = dt_to_str(
                        next_start
                    )
                    update_items["submit"]["mark_complete"] = False
                elif not next_token and not deferred_page_token:
                    latest_data_value = rsp.get(
                        "latest_data_override", end_time_str
                    )
                    update_items["submit"]["set_latest_data"] = latest_data_value
                    update_items["submit"]["mark_complete"] = True
                if resource.store_page_token():
                    update_items["latest_page_token"] = (
                        deferred_page_token or next_token
                    )
                    update_items["last_page_token_update"] = dt_to_str(now())
                    # the stale marker skips schedules that are deliberately
                    # waiting on the vendor before advancing latest_data
                    update_items["deferred"] = bool(deferred_page_token)
                if resource.store_current_crawl_params():
                    if next_start:
                        # only the end is safe to write now. the start moves in
                        # advance_latest_data, once this window's rows have finished submitting
                        update_items["current_crawl_end"] = end_time_str
                    elif next_token:
                        update_items["current_crawl_start"] = dt_to_str(
                            current_start_dt
                        )
                        update_items["current_crawl_end"] = end_time_str
                    elif deferred_page_token:
                        # royal mail leaves without a latest_data write, so nothing
                        # downstream is coming to clear these
                        update_items["current_crawl_start"] = None
                        update_items["current_crawl_end"] = None
                update_crawl_items(connection_id, function_name, update_items)
            logger.info(
                f"Wrote {len(data)} items to submitter lambda s3 for table {table_name}: page {page}"
            )
        total_rows_submitted += len(data)
        page += 1
        if max_pages and page > max_pages:
            logger.info(f"Reached max_pages limit ({max_pages}), stopping crawl")
            break
        if next_start:
            if not DRY_RUN:
                wait_for_submit_drain(
                    connection_id,
                    function_name,
                    dt_to_str(next_start),
                    sync_job_id=sync_job_id,
                )
            current_start_dt = next_start
            start_time_dt = next_start
            next_token = "default"

# enqueue an async refresh of every linked record whose FK appeared this
# task; the linked-refresh lambda owns fetch + persist + webhook (retry/DLQ).
if linked_ids_seen:
    try:
        start_str = dt_to_str(start_time_dt)
        end_str = dt_to_str(end_time_dt)
        if local_submit:
            from lambda_handlers.linked_refresh import refresh_linked_resources

            refresh_linked_resources(
                resource,
                sorted(linked_ids_seen),
                start_str,
                end_str,
                local_submit=True,
            )
        elif not DRY_RUN:
            payload = {
                "resource": resource.trimmed(),
                "data": sorted(linked_ids_seen),
                "start": start_str,
                "end": end_str,
                "tracking_id": "",
            }
            write_pickle_to_s3("linked-refresh", payload, "linked_refresh")
    except Exception as e:
        logger.error(f"linked-refresh enqueue failed for {resource.name()}: {e}")

if not DRY_RUN:
    current_time = dt_to_str(now())
    # submitter may finish before we get here (e.g. last page has no data)
    # check that crawl/sync jobs are complete and send relevant webhooks
    if sync_job_id:
        update_sync_job_rsp = update_sync_job(
            sync_job_id,
            {
                "last_crawl_end": current_time,
                "latest_page_token": None,
            },
        )
        if should_sync_job_complete(update_sync_job_rsp["Attributes"]):
            logger.info("All submit tasks finished, setting sync job status")
            complete_sync_job(
                sync_job_id, update_sync_job_rsp["Attributes"], resource
            )
    else:
        update_items = {"last_crawl_end": current_time}
        update_crawl_rsp = update_crawl_items(
            connection_id, function_name, update_items

    if log_context:
        logger.updateConfig(log_context)
    while not stop_event.is_set():
        current_time = dt_to_str(now())
        logger.info(f"Heartbeat sent from {worker_hostname} at {current_time}")
        if sync_job_id:
            update_sync_job(sync_job_id, {"latest_heartbeat": current_time})
        else:
            update_crawl_items(
                connection_id, function_name, {"latest_heartbeat": current_time}
            )
        sleep(HEARTBEAT_INTERVAL)


def wait_for_submit_drain(connection_id, function_name, next_start, sync_job_id=None):
    # wait for the submitter to finish all tasks for this crawl window before advancing latest_data
    logger.info(f"Waiting for submit tasks to drain through {next_start}")
    deadline = now() + timedelta(seconds=SUBMIT_DRAIN_TIMEOUT)
    while now() < deadline:
        if sync_job_id:
            row = get_sync_job(sync_job_id)
        else:
            row = get_scheduler_row(connection_id, function_name)
        if row.get("latest_data") == next_start:
            return
        if should_update_latest_data(row):
            if sync_job_id:
                advance_sync_job_latest_data(sync_job_id, row)
            else:
                advance_latest_data(connection_id, function_name, row)
            return
        sleep(SUBMIT_DRAIN_POLL)
    raise PokedexException(
        f"Submit tasks did not drain through {next_start} in {SUBMIT_DRAIN_TIMEOUT}s",
        500,
        origin="trackstar",
    )


def message_enqueued_at(request):
    # a worker exposes custom message headers as request attributes; an eager
    # run (tests, yarn crawl) keeps them under request.headers
    headers = request.headers or {}
    return request.get("enqueued_at") or headers.get("enqueued_at")


def crawl_superseded(enqueued_at, schedule_row):
    if not enqueued_at:
        return False
    last_crawl_start = schedule_row.get("last_crawl_start")
    last_crawl_end = schedule_row.get("last_crawl_end")
    if not last_crawl_start or not last_crawl_end:
        return False
    started = str_to_dt(last_crawl_start)
    ended = str_to_dt(last_crawl_end)
    return started >= str_to_dt(enqueued_at) and ended >= started


def _execute_crawl_task(
    self,
    connection_row,
    org_row,
    function_name,
    first_crawl,
    start_time_str,
    end_time_str,
    page_token,
    force=False,
    local_submit=False,
    no_heartbeat=False,
    protected=False,
    sync_job_id=None,
):
    # ecs agent should reject celery tasks when scale-in event is received
    if shutdown_requested:
        logger.info("shutdown requested - rejecting new crawl task")
        raise self.reject(requeue=True)

    connection_id = connection_row["id"]
    integration_secret = connection_row["integration_secret"]
    integration_name = connection_row["integration_name"]
    created_at = connection_row["created_at"]
    integration_type = connection_row["integration_type"]
    org_id = org_row["id"]
    org_name = org_row["name"]

    if sync_job_id:
        # synced crawl - check sync job status
        row_to_check = get_sync_job(sync_job_id)
        if not row_to_check:
            logger.error(f"Sync job {sync_job_id} not found")
            return
        if row_to_check["status"] != "open":
            logger.info(
                f"Sync job {sync_job_id} is no longer open (status: {row_to_check['status']})"
            )
            return
    else:
        # regular crawl - check scheduler row
        row_to_check = get_scheduler_row(connection_id, function_name)

    stale = row_to_check.get("stale", False)
    paused = row_to_check.get("paused", False)
    force_sync_pending = bool(row_to_check.get("force_sync_pending"))
    if crawl_heartbeat_active(row_to_check) and crawl_started(row_to_check):
        logger.info(
            f"Crawl task {function_name} for connection {connection_id} is already running"
        )
        if not DRY_RUN:
            if force:
                # force overrides the already-running guard. prompt only when a human is
                # driving; a worker has no stdin, so input() there raises EOFError and kills
                # the crawl instead of honoring the explicit force.
                if sys.stdin and sys.stdin.isatty():
                    to_continue = input(
                        "Crawl is already running. Do you want to continue? (y/n): "
                    )
                    if to_continue.lower() != "y":
                        logger.info("Exiting crawl task")
                        return
            else:
                return
    # a dead worker's crawl comes back from both sqs and the scheduler. once one
    # copy has finished, the other would only crawl the same window again
    regular_crawl = not sync_job_id and not force and not force_sync_pending
    if regular_crawl and crawl_superseded(
        message_enqueued_at(self.request), row_to_check
    ):
        logger.info(
            f"Crawl task {function_name} for connection {connection_id} already "
            "ran again since this copy was queued, skipping"
        )
        return

    try:
        org_private_key = get_org_private_key(org_id)
    except Exception as e:
        logger.error(f"Error getting org private key: {format_exception(e)}")
        raise Exception(f"org private key not found for {org_id}")
    try:
        integration_secret = org_decrypt(integration_secret, org_private_key)
    except Exception:
        raise Exception("integration secret could not be decoded")

    integration = build_integration(
        connection_row, org_id, integration_secret=integration_secret
    )
    # log crawl id for browserbase tracking
    crawl_id = integration.crawl_id
    logger.updateConfig({"crawl_id": crawl_id})

    }

def get_orders(
    self,
    start,
    end,
    first_crawl,
    first_loop,
    page_token={"create": 1, "update": 1},
    sync_job_id=None,
):
    if first_loop:
        if not self.in_perm_validator():
            shipping_methods = ShippingMethod(self).get_all_resources()
        else:
            shipping_methods = []
        self.shipping_method_name_to_id = {
            str(sm["name"]): sm["id"] for sm in shipping_methods
        }
        self.warehouse_id_to_address = defaultdict(dict)
        if not self.in_perm_validator():
            self.warehouse_id_to_address = {}
            warehouses = Warehouse(self).get_all_resources()
            for warehouse in warehouses:
                self.warehouse_id_to_address[warehouse["id"]] = warehouse.get(
                    "address"
                )
        # shipbob only echoes the kit's own sku on shipment picks, so kit
        # detection and component skus come from the synced product catalog
        self.sku_to_is_kit = {}
        self.kit_component_skus = {}
        if not self.in_perm_validator():
            # fulfilled orders never re-format, so their kit labels would stay
            # wrong forever if formatted before the catalog finishes syncing
            Product(self).check_first_crawl_complete()
            products = Product(self).get_all_resources()
            for product in products:
                self.sku_to_is_kit[product["sku"]] = product["is_kit"]
                for component in product["inventory_items"]:
                    self.kit_component_skus[component["inventory_item_id"]] = (
                        component["sku"]
                    )
        # shipbob doesn't return cancelled orders when filtering by updated date
        # so we need to individually lookup open orders that aren't found in our 2 api queries (created/update)
        self.previously_seen_open_order_ids = set()
        # exception/backordered orders go back to processing once stock arrives,
        # so they can still change and need the same lookup
        order_statuses_to_review = [
            "open",
            "processing",
            "partially_fulfilled",
            "exception",
            "backordered",
        ]
        if not first_crawl and not self.in_perm_validator() and not sync_job_id:
            order_ids_to_review = []
            for status in order_statuses_to_review:
                previously_seen_status_orders = Order(self).get_all_resources(
                    {"status": {"eq": status}}
                )
                for order in previously_seen_status_orders:
                    order_ids_to_review.append(order["id"])
            # a different slice each crawl: an order that is genuinely still open
            # never changes, so a fixed ordering would re-check the same ones forever
            if len(order_ids_to_review) > ORDER_RELOOKUP_LIMIT:
                order_ids_to_review = random.sample(
                    order_ids_to_review, ORDER_RELOOKUP_LIMIT
                )
            for order_id in order_ids_to_review:
                self.previously_seen_open_order_ids.add(order_id)

    query_start = start
    # on regular crawls get smaller window of time
    days_to_get = timedelta(days=7) if first_crawl else timedelta(hours=1)
    query_end = min(query_start + days_to_get, end)

    url = self.get_url("order")

    # orders that have been created without modification are not returned with LastUpdateStartDate
    create_query_params = {
        "Page": page_token["create"],
        "Limit": PAGE_SIZE,
        "StartDate": dt_to_str(query_start),
        "EndDate": dt_to_str(query_end),
    }
    update_query_params = {
        "Page": page_token["update"],
        "Limit": PAGE_SIZE,
        "LastUpdateStartDate": dt_to_str(query_start),
        "LastUpdateEndDate": dt_to_str(query_end),
    }

    next_token = {"create": None, "update": None}

    raw_orders = []
    if page_token["create"] is not None:
        create_response = self.shipbob_request(
            url, query_params=create_query_params
        )
        raw_orders.extend(create_response)
        if len(create_response) == PAGE_SIZE:
            next_token["create"] = page_token["create"] + 1
    if page_token["update"] is not None:
        update_response = self.shipbob_request(
            url, query_params=update_query_params
        )
        raw_orders.extend(update_response)
        if len(update_response) == PAGE_SIZE:
            next_token["update"] = page_token["update"] + 1

    orders = []
    order_ids = set()
    for item in raw_orders:
        order = format_order(
            item,
            self.get_shipbob_app_url(),
            self.warehouse_id_to_address,
            self.shipping_method_name_to_id,
            self.sku_to_is_kit,
            self.kit_component_skus,
        )
        if order["id"] not in order_ids:
            orders.append(order)
            order_ids.add(order["id"])

    self.previously_seen_open_order_ids -= order_ids

    next_start = None
    if not next_token["create"] and not next_token["update"]:
        next_token = None
        if query_end < end:
            next_start = query_end
        else:
            # final day — do open-order lookup then finish
            if self.previously_seen_open_order_ids:
                remaining_ids = list(self.previously_seen_open_order_ids)
                for i in range(0, len(remaining_ids), ORDER_ID_LOOKUP_CHUNK_SIZE):
                    chunk = remaining_ids[i : i + ORDER_ID_LOOKUP_CHUNK_SIZE]
                    ids_param = ",".join(chunk)
                    raw_remaining = self.shipbob_request(
                        url,
                        query_params={
                            "IDs": ids_param,
                            "Limit": ORDER_ID_LOOKUP_CHUNK_SIZE,
                        },
                    )
                    for item in raw_remaining:
                        order = format_order(
                            item,
                            self.get_shipbob_app_url(),
                            self.warehouse_id_to_address,
                            self.shipping_method_name_to_id,
                            self.sku_to_is_kit,
                            self.kit_component_skus,
                        )
                        orders.append(order)

    return {"data": orders, "next_token": next_token, "next_start": next_start}

def allow_orders_on_demand_sync(self):

        # TODO ticket open to pass in sku directly to api
        inventory_item = {
