def format_iso(date_str):
    if not date_str:
        return None
    if "." in date_str:
        date_str = date_str.split(".")[0]
    return dt_to_str(datetime.fromisoformat(date_str))


def chunk_dates(from_date, to_date, chunk_days):
    # slice an inclusive [from_date, to_date] "YYYY-MM-DD" range into spans of at most
    # chunk_days, newest span first. spans are day-adjacent (no overlap, no gap) so a
    # date filtered by an inclusive [from, to] query lands in exactly one span
    start = datetime.strptime(from_date, "%Y-%m-%d").date()
    end = datetime.strptime(to_date, "%Y-%m-%d").date()
    if start > end:
        return []
    spans = []
    cursor = start
    while cursor <= end:
        span_end = min(cursor + timedelta(days=chunk_days - 1), end)
        spans.append((cursor.strftime("%Y-%m-%d"), span_end.strftime("%Y-%m-%d")))
        cursor = span_end + timedelta(days=1)
    spans.reverse()
    return spans


