    # date filtered by an inclusive [from, to] query lands in exactly one span
    start = datetime.strptime(from_date, "%Y-%m-%d").date()
    end = datetime.strptime(to_date, "%Y-%m-%d").date()
    if start > end:
        return []
    spans = []
    cursor = start
    while cursor <= end:
        span_end = min(cursor + timedelta(days=chunk_days - 1), end)
        spans.append((cursor.strftime("%Y-%m-%d"), span_end.strftime("%Y-%m-%d")))
        cursor = span_end + timedelta(days=1)
    spans.reverse()
    return spans


