def get_inventory(self, start, end, first_crawl, first_loop, page_token={}):
    if self.org_id in PACKIYO_ALWAYS_FULL_INVENTORY_CRAWL_ORGS:
        first_crawl = True

    if first_loop:
        self.get_customer_to_units_map()
        # get warehouse to location map
        warehouse_locations = WarehouseLocation(self).get_all_resources()
        self.location_to_warehouse = {
            location["id"]: location["warehouse_id"]
            for location in warehouse_locations
        }

    path = "products"
    page = page_token.get("page", 1)
    query_params = {
        "page[size]": PAGE_SIZE,
        "page[number]": page,
        "include": "location_products.location,customer",
    }
    if not first_crawl:
        query_start = (
            start if not page_token.get("start") else str_to_dt(page_token["start"])
        )
        query_end = min(query_start + timedelta(minutes=5), end)
        query_params["filter[updated_at_min]"] = dt_to_str(query_start)[:-1]
        query_params["filter[updated_at_max]"] = dt_to_str(query_end)[:-1]

    inventory_data = self.packiyo_request(path, params=query_params)
    additional_data = defaultdict(dict)
    included_data = inventory_data.get("included", [])
    for item in included_data:
        if item["type"] == "location-products":
            if not item["relationships"]["location"][
                "data"
            ] or not self.location_to_warehouse.get(
                item["relationships"]["location"]["data"]["id"]
            ):
                location_id = None
                warehouse_id = None
            else:
                warehouse_id = self.location_to_warehouse[
                    item["relationships"]["location"]["data"]["id"]
                ]
                location_id = item["relationships"]["location"]["data"]["id"]
            additional_data["location_products"][item["id"]] = {
                **item["attributes"],
                "location_id": location_id,
                "warehouse_id": warehouse_id,
            }
    formatted_inventory = []
    for item in inventory_data["data"]:
        if item["attributes"]["type"] == "kit":
            continue
        location_products = []
        for location_product in item["relationships"]["location_products"]["data"]:
            location_product_id = location_product["id"]
            location_product_data = additional_data["location_products"][
                location_product_id
            ]
            location_products.append(location_product_data)
        formatted_inv_item = format_inventory(
            item,
            location_products,
            self.integration_secret["tenant_name"],
            self.customer_units,
        )
        formatted_inventory.append(formatted_inv_item)

    next_token = None
    if first_crawl:
        if inventory_data["links"].get("next"):
            next_token = {"page": page + 1}
    else:
        if inventory_data["links"].get("next"):
            next_token = {
                "start": dt_to_str(query_start),
                "page": page + 1,
            }
        elif query_end < end:
            next_token = {
                "start": dt_to_str(query_end),
                "page": 1,
            }

    return {"data": formatted_inventory, "next_token": next_token}

