def get_orders(
    self, start, end, first_crawl, first_loop, page_token=None, sync_job_id=None
):
    warehouse_customer_id = self.customer_id
    if first_loop:
        self.get_wh_id_to_info()
        self.channel_name_map = {}
        channels = self.get_order_channels(first_loop, [])
        for channel in channels["data"]:
            channel_name = channel["name"]
            if channel_name in self.channel_name_map:
                raise PokedexException(
                    f"Duplicate channel name: {channel_name}",
                    500,
                    origin="trackstar",
                )
            self.channel_name_map[channel_name] = channel
        self.get_shipping_methods(start, end, first_crawl, first_loop)

    # 1 day when catching up, else 30 min: the short window has to outlast
    # crawl_start_overlap_minutes or the first window ends before the saved start
    if first_crawl or end - start > timedelta(days=1):
        window_end = start + timedelta(days=1)
    else:
        window_end = start + timedelta(minutes=30)
    window_end = min(window_end, end)
    query_start_str = dt_to_str(start)
    query_end_str = dt_to_str(window_end)

    path = "orders/sales"
    params = {
        "after": page_token,
        "updated_at_start_date": query_start_str,
        "updated_at_end_date": query_end_str,
        "limit": 100,
    }
    response = self.stord_request(path, params=params)
    next_cursor = response["metadata"]["after"]
    results = response["data"]

    orders_by_id = {}
    for result in results:
        shipment_path = "orders/confirmations/shipments"
        shipment_params = {
            "filter[order_number]": result["order_number"],
            "limit": 100,
        }
        shipment_response = self.stord_request(
            shipment_path, params=shipment_params
        )
        shipments = shipment_response["data"]
        formatted_order = format_order(
            result,
            shipments,
            self.wh_id_to_info,
            self.channel_name_map,
            self.get_external_url_base(),
            self.carrier_name_scac_to_id,
            self.sm_name_to_id,
            warehouse_customer_id,
        )
        if not formatted_order["id"] or formatted_order["id"].lower() == "none":
            continue
        order_id = formatted_order["id"]
        # stord reuses order_number across distinct sales orders (real key is
        # order_id), so a page can repeat a canonical id; keep the best one
        if order_id in orders_by_id:
            if order_dedup_key(orders_by_id[order_id]) >= order_dedup_key(
                formatted_order
            ):
                continue
        orders_by_id[order_id] = formatted_order

    orders = list(orders_by_id.values())

    next_token = None
    next_start = None
    if next_cursor:
        next_token = next_cursor
    elif window_end < end:
        next_start = window_end

    return {"data": orders, "next_token": next_token, "next_start": next_start}

